function UIBattlingLevelTipsDialog:ShowTips(tipsList)
    --- Title
    self.TitleText.text = tipsList[1]
    --- 描述
    for i = 2, #tipsList do
        local goTxtDesc = CS.UnityEngine.GameObject.Instantiate(self.TxtNode.gameObject, self.TipPanel)
        local txtDesc = goTxtDesc:GetComponent(typeof(CS.UnityEngine.UI.Text))
        if not IsNull(txtDesc) then
            txtDesc.text = tipsList[i]
        end
        KTool.SetActive(goTxtDesc, true)
    end
end

function UIBattlingLevelTipsDialog:Refresh(tipsList, position)
    self:ShowTips(tipsList)
    self.TipPanel.anchoredPosition = position + PositionOffset
end

